import { z } from "zod";

/** The longest message a person can send the coach, in characters. */
export const CHAT_MESSAGE_MAX_LENGTH = 2000;

/**
 * Body of POST /chat: only the new message. The browser never sends the
 * conversation; the API builds the model's context from the database.
 * `id` is generated by the browser, so a retry of the same message reuses its
 * saved entry instead of creating a second one.
 */
export const ChatMessageRequestSchema = z.object({
  id: z.uuid(),
  text: z.string().trim().min(1).max(CHAT_MESSAGE_MAX_LENGTH),
});
export type ChatMessageRequest = z.infer<typeof ChatMessageRequestSchema>;

/** One message in GET /chat/messages, oldest first. */
export const ChatHistoryMessageSchema = z.object({
  id: z.uuid(),
  role: z.enum(["user", "assistant"]),
  text: z.string(),
  createdAt: z.iso.datetime(),
});
export type ChatHistoryMessage = z.infer<typeof ChatHistoryMessageSchema>;

export const ChatHistoryResponseSchema = z.object({
  messages: z.array(ChatHistoryMessageSchema),
});
export type ChatHistoryResponse = z.infer<typeof ChatHistoryResponseSchema>;
